Definition leaf_chk_f (i : nat) (c : CC.cutpoint) (k : nat) (ps : SR.post_spec) (t : CC.tag) : bool :=
  match t with
  | CC.TGoto _ _ => false
  | CC.TOther pc =>
      let cells := SR.ps_cells ps in
      match CH2.ret_of F.RETS i k with
      | Some j =>
          match nth_error F.CPS j with
          | Some cj =>
              (Z.eqb pc PC_MM && Z.eqb (SR.ps_pc ps) PC_MM && Nat.eqb i 0 && Nat.eqb j 1 && CH2.blocks_eqb (nth i F.BLS []) BOLD && CH2.blocks_eqb (nth j F.BLS []) BOLD
               && CHA.foot_chk FT.NF F.HDECL c BOLD [] && CBA.regions_eqb (CC.cp_F c) CP0
               && isSome (CHA.custom_chk FT.NF F.HDECL FT.SCELLS FT.GLO FT.GHI 2560 0 BOLD [] [(PSZ, 0, nE)] NEWS_F (Some PSZ) c ps cj BOLD [] BOLD [])
               && CL.ps_reg_is ps 10 PSZ && CL.ps_reg_is ps 11 qE && CL.ps_reg_is ps 12 nE)%bool
          | None => false
          end
      | None =>
          (Z.eqb pc RETPC && Nat.eqb i 1 && CBA.exit_base_chk FT.NF RETPC c ps && CHA.foot_chk FT.NF F.HDECL c BOLD [] && CH2.blocks_eqb (nth i F.BLS []) BOLD
